/****************************************************************************
 * Name: rk3576_vicap_worker_quiesce
 *
 * Description:
 *   Wait until no frame worker is queued and none is running, so that the
 *   caller may release or replace the buffers a worker reads and writes.
 *
 *   The worker latches the RAW buffer it reads and the framework's buffer it
 *   writes at the top, and keeps both for the whole demosaic.  The epoch
 *   check at its end stops a frame from the old stream being *delivered*,
 *   but it says nothing about the reads and writes that happened before it,
 *   against memory that may already have gone back to a heap.  Every path
 *   that lets go of, or re-points, one of those buffers therefore has to be
 *   ordered after the worker has finished, and this is that ordering.
 *
 *   work_cancel_sync() is the handshake: it drops a worker that is queued but
 *   has not started, and waits for one that is already running to return.
 *   It is asleep only for the second case, and it is safe to call from the
 *   worker's own thread -- the work queue waits only on work being processed
 *   by a different thread -- which matters because the framework reaches
 *   stop_capture() from the completion callback.
 *
 *   It sleeps, so it belongs only on paths that may block: the framework's
 *   close and REQBUFS through the free() hook, and this driver's own
 *   reconfiguration and take-down.  It must never be reached from
 *   stop_capture(), which the framework calls from complete_capture() with a
 *   spinlock held and preemption disabled.  A cancelled worker leaves
 *   frame_scheduled set; start_capture() clears it, and with the capture path
 *   stopped nothing can queue another worker in the meantime.
 *
 ****************************************************************************/

static void rk3576_vicap_worker_quiesce(FAR struct rk3576_vicap_s *priv)
{
  /* -ENOENT is the ordinary answer -- nothing was queued and nothing was
   * running -- and the other answers are not failures of interest here, so
   * the result is deliberately not reported.
   */

  (void)work_cancel_sync(LPWORK, &priv->work);
}
